#include <bits/stdc++.h>
using namespace std;
int n,z[24];int64_t H[24][24],h[24],q;uint32_t keys[24],vkey;double d[24],mu[24][24],shift[24],radius,c;vector<uint16_t> tab;ofstream out;uint64_t hist[25]={},weighted=0,nodes=0;bool raw;int shell=10;auto start=chrono::steady_clock::now();
void visit(int k,double partial,__int128 exact,uint32_t key){
 if(k<0){__int128 full=exact+q;if(full<0||full>radius)return;int64_t norm=(int64_t)full;if(norm%2){cerr<<"odd norm";exit(2);}hist[norm]++;if(raw){if(norm==4)out.write((char*)&key,4);}else{int64_t w=0;if(shell==8){switch(norm){case 0:w=9828000;break;case 4:w=12800;break;case 6:w=192;break;case 8:w=tab[key];break;default:w=0;}weighted+=w;return;}switch(norm){case 0:w=1610219520;break;case 4:w=9523200;break;case 6:w=441600;break;case 8:w=12800-48*int(tab[key]);break;case 10:w=192;break;case 12:w=tab[key];break;default:cerr<<"unexpected norm"<<norm;exit(3);}if(w<0){cerr<<"negativeweight";exit(4);}weighted+=w;}return;}
 nodes++;if((nodes&((1ULL<<27)-1))==0)cerr<<nodes<<" nodes count "<<weighted<<" sec "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<endl;
 double cen=shift[k];for(int j=k+1;j<n;j++)cen+=mu[j][k]*(z[j]+shift[j]);double b=sqrt(max(0.,(radius-c+1e-7-partial)/d[k]));int lo=ceil(-cen-b-1e-8),hi=floor(-cen+b+1e-8);__int128 lin=h[k];for(int j=k+1;j<n;j++)lin+=(__int128)H[k][j]*z[j];
 for(int x=lo;x<=hi;x++){double next=partial+d[k]*(x+cen)*(x+cen);if(next>radius-c+1e-7)continue;z[k]=x;visit(k-1,next,exact+(__int128)H[k][k]*x*x+2*lin*x,key^((x&1)?keys[k]:0));}}
int main(int argc,char**argv){if(argc!=4&&argc!=5)return 1;if(argc==5)shell=stoi(argv[4]);ifstream f(argv[1]);f>>n>>radius>>q>>c>>vkey;for(int i=0;i<n;i++)for(int j=0;j<n;j++)f>>H[i][j];for(int i=0;i<n;i++)f>>h[i];for(int i=0;i<n;i++)f>>keys[i];for(int i=0;i<n;i++)f>>d[i];for(int i=0;i<n;i++)f>>shift[i];for(int i=0;i<n;i++)for(int j=0;j<n;j++)f>>mu[i][j];if(!f)return 1;raw=string(argv[2])=="raw";if(raw)out.open(argv[3],ios::binary);else{tab.resize(1<<24);ifstream t(argv[2],ios::binary);t.read((char*)tab.data(),tab.size()*2);if(!t)return 5;}visit(n-1,0,0,vkey);cout<<"{\"weighted\":"<<weighted<<",\"nodes\":"<<nodes<<",\"hist\":{";bool first=true;for(int i=0;i<25;i++)if(hist[i]){if(!first)cout<<",";first=false;cout<<"\""<<i<<"\":"<<hist[i];}cout<<"},\"seconds\":"<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"}"<<endl;}
